import torch
import torch.nn as nn

# PTX kernel implementing fp16 LayerNorm (no affine parameters)
PTX_SOURCE = r"""
.version 8.5
.target sm_120a
.address_size 64

.shared .align 4 .b8 s_sum[1024];      // 256 threads * 4 bytes
.shared .align 4 .b8 s_sumsq[1024];    // 256 threads * 4 bytes

.visible .entry layernorm(
    .param .u64 layernorm_param_0,   // input  fp16*
    .param .u64 layernorm_param_1,   // output fp16*
    .param .u32 layernorm_param_2,   // batch size (B)
    .param .u32 layernorm_param_3    // elements per batch (N)
)
{
    //--- registers -------------------------------------------------
    .reg .pred   %p<6>;
    .reg .b32    %r<12>;
    .reg .b64    %rd<24>;

    .reg .f32    %f<15>;
    .reg .f16    %h<5>;

    //--- load kernel arguments ------------------------------------
    ld.param.u64    %rd1, [layernorm_param_0];
    ld.param.u64    %rd2, [layernorm_param_1];
    ld.param.u32    %r1,  [layernorm_param_2];   // batch size B
    ld.param.u32    %r2,  [layernorm_param_3];   // N (elements per batch)

    //--- thread / block identifiers -------------------------------
    mov.u32         %r3, %ctaid.x;    // batch index
    mov.u32         %r4, %ntid.x;    // blockDim.x
    mov.u32         %r5, %tid.x;     // threadIdx.x

    //--- bounds check: if batch index >= B exit -----------------
    setp.ge.u32     %p1, %r3, %r1;
    @%p1 bra        $L_EXIT;

    //--- convert generic pointers to global address space ----------
    cvta.to.global.u64 %rd3, %rd1;   // in_ptr
    cvta.to.global.u64 %rd4, %rd2;   // out_ptr

    //--- compute base byte offset for this batch -----------------
    // element offset = batchIdx * N (elements)
    mul.wide.u32    %rd5, %r3, %r2;          // %rd5 = batchIdx * N (elements)
    mul.wide.u32    %rd6, %rd5, 2;          // %rd6 = *2  (bytes, fp16)

    // in_base = in_ptr + byte_offset
    add.s64         %rd7, %rd3, %rd6;
    // out_base = out_ptr + byte_offset
    add.s64         %rd8, %rd4, %rd6;

    //--- first pass: compute per‑thread partial sums ----------------
    // initialize per‑thread accumulators (float32)
    mov.f32         %f2, 0.0;   // sum
    mov.f32         %f3, 0.0;   // sumsq

    // loop index i = threadIdx.x
    mov.u32         %r6, %r5;   // i

$LOOP_SUM:
    setp.ge.u32     %p2, %r6, %r2;      // i >= N ?
    @%p2 bra        $END_LOOP_SUM;

    // compute address of element i
    mul.wide.u32    %rd9, %r6, 2;       // offset_bytes = i*2
    add.s64         %rd10, %rd7, %rd9;  // addr = in_base + offset

    // load fp16, convert to fp32
    ld.global.f16   %h1, [%rd10];
    cvt.f32.f16     %f1, %h1;

    // accumulate
    add.f32         %f2, %f2, %f1;            // sum
    mul.f32         %f4, %f1, %f1;
    add.f32         %f3, %f3, %f4;            // sumsq

    // i += blockDim.x
    add.u32         %r6, %r6, %r4;
    bra             $LOOP_SUM;

$END_LOOP_SUM:

    // store per‑thread partial sums into shared memory
    // byte offset = threadIdx.x * 4
    mul.wide.u32    %rd11, %r5, 4;          // offset in bytes

    // address of s_sum[tid]
    mov.u64         %rd12, s_sum;
    add.u64         %rd13, %rd12, %rd11;
    st.shared.f32   [%rd13], %f2;

    // address of s_sumsq[tid]
    mov.u64         %rd14, s_sumsq;
    add.u64         %rd15, %rd14, %rd11;
    st.shared.f32   [%rd15], %f3;

    bar.sync 0;      // make sure all sums are visible

    //--- reduction on thread 0 to get total sum and sumsq ----------
    setp.ne.u32     %p3, %r5, 0;     // only thread 0 proceeds
    @%p3 bra        $AFTER_REDUCE;

    // thread 0: initialize totals
    mov.f32         %f5, 0.0;   // total_sum
    mov.f32         %f6, 0.0;   // total_sumsq

    mov.u32         %r7, 0;     // j = 0

$REDUCTION_LOOP:
    setp.ge.u32     %p4, %r7, %r4;
    @%p4 bra        $REDUCTION_END;

    // load per‑thread sum
    mul.wide.u32    %rd16, %r7, 4;
    mov.u64         %rd17, s_sum;
    add.u64         %rd18, %rd17, %rd16;
    ld.shared.f32   %f7, [%rd18];
    add.f32         %f5, %f5, %f7;

    // load per‑thread sumsq
    mov.u64         %rd19, s_sumsq;
    add.u64         %rd20, %rd19, %rd16;
    ld.shared.f32   %f8, [%rd20];
    add.f32         %f6, %f6, %f8;

    add.u32         %r7, %r7, 1;
    bra             $REDUCTION_LOOP;

$REDUCTION_END:
    // compute mean = total_sum / N
    cvt.f32.u32     %f9, %r2;                // N as float
    div.f32         %f10, %f5, %f9;          // mean

    // compute variance = (total_sumsq / N) - mean*mean
    div.f32         %f11, %f6, %f9;          // total_sumsq/N
    mul.f32         %f12, %f10, %f10;        // mean*mean
    sub.f32         %f11, %f11, %f12;        // var

    // epsilon = 1e-5
    mov.f32         %f13, 1e-05;
    add.f32         %f11, %f11, %f13;        // var + eps
    rsqrt.approx.f32 %f14, %f11;            // inv_std = 1/sqrt(var+eps)

    // store mean and inv_std to shared for broadcast
    mov.u64         %rd21, s_sum;
    st.shared.f32   [%rd21], %f10;          // mean
    mov.u64         %rd22, s_sumsq;
    st.shared.f32   [%rd22], %f14;          // inv_std

    // end of thread‑0 exclusive section
$AFTER_REDUCE:
    bar.sync 0;      // broadcast mean & inv_std

    //--- broadcast mean & inv_std to all threads -------------------
    mov.u64         %rd23, s_sum;
    ld.shared.f32   %f10, [%rd23];          // mean
    mov.u64         %rd24, s_sumsq;
    ld.shared.f32   %f14, [%rd24];          // inv_std

    //--- second pass: write normalized values ----------------------
    // reuse loop index i = threadIdx.x
    mov.u32         %r6, %r5;   // i

$LOOP_NORM:
    setp.ge.u32     %p5, %r6, %r2;
    @%p5 bra        $END_LOOP_NORM;

    // compute address of element i
    mul.wide.u32    %rd9, %r6, 2;
    add.s64         %rd10, %rd7, %rd9;   // in address
    ld.global.f16   %h2, [%rd10];
    cvt.f32.f16     %f1, %h2;

    // normalize: (x - mean) * inv_std
    sub.f32         %f1, %f1, %f10;
    mul.f32         %f1, %f1, %f14;

    // convert back to fp16
    cvt.rn.f16.f32  %h3, %f1;

    // store to output
    add.s64         %rd10, %rd8, %rd9;   // out address (same offset)
    st.global.f16   [%rd10], %h3;

    // i += blockDim.x
    add.u32         %r6, %r6, %r4;
    bra             $LOOP_NORM;

$END_LOOP_NORM:
$L_EXIT:
    ret;
}
"""

class ModelNew(nn.Module):
    def __init__(self, *_, **__):
        """Accept any extra arguments for compatibility with the original API."""
        super().__init__()
        # Load the PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Apply LayerNorm (no learnable weight/bias) to the last dimensions of x.
        Expects x of dtype torch.float16.
        """
        assert x.dtype == torch.float16, "Input must be FP16"
        B = x.shape[0]                       # batch size
        N = x.numel() // B                    # elements per batch (flattened)

        out = torch.empty_like(x)

        block = 256
        grid = (B, 1, 1)

        # Launch kernel: input ptr, output ptr, batch size, elements per batch
        ptx_launch(
            self.module,
            "layernorm",
            grid,
            (block, 1, 1),
            [x.data_ptr(), out.data_ptr(), B, N]
        )
        return out
